          <section class="form-section" aria-labelledby="page-title">
            <form id="notification-form">
              ${NotificationQuestion()}
              <div class="submit-row">
                <button type="submit">Submit</button>
                <p class="status" id="form-status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        </div>
      `;
    }

    document.querySelector("#main-content").innerHTML = App();

    document.querySelector("#notification-form").addEventListener("submit", function (event) {
      event.preventDefault();
      const data = new FormData(event.currentTarget);
      const selection = data.get("notificationPreference");
      const status = document.querySelector("#form-status");
      status.textContent = "Preference saved: " + selection;
    });
  </script>
