     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-width: 0;
     }

     legend {
       margin-bottom: 1rem;
       padding: 0;
       font-size: 1.125rem;
       font-weight: 700;
     }

     .helper-text {
       margin: -0.4rem 0 1rem;
       color: var(--muted);
       line-height: 1.5;
     }

     .option-list {
       display: grid;
       gap: 0.85rem;
     }

     .option-card {
       display: flex;
       align-items: center;
       gap: 0.9rem;
       padding: 1rem 1.05rem;
       border: 1px solid var(--panel-border);
       border-radius: 1rem;
       background: #111620;
       transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
     }

     .option-card:hover {
       border-color: var(--accent);
       background: #141b2a;
       transform: translateY(-1px);
     }

     .option-card:focus-within {
       outline: 3px solid var(--accent-strong);
