   <script>
     const notificationOptions = [
       { id: "email", label: "Email" },
       { id: "sms", label: "SMS" },
       { id: "push", label: "Push Notifications" }
     ];

     function NotificationOption(option) {
       return `
         <div class="option-card">
           <input type="radio" id="${option.id}" name="notificationPreference" value="${option.label}" required>
           <label for="${option.id}">${option.label}</label>
         </div>
       `;
     }

     function NotificationQuestion() {
       return `
         <div class="form-field">
           <fieldset aria-describedby="notification-help">
             <legend>How do you prefer to receive notifications?</legend>
             <p class="helper-text" id="notification-help">Choose one option to set your preferred notification channel.</p>
             <div class="option-list">
               ${notificationOptions.map(NotificationOption).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function App() {
       return `
         <div class="shell">
           <section class="hero" aria-labelledby="page-title">
             <p class="eyebrow">Preferences</p>
             <h1 id="page-title">Stay in the loop</h1>
             <p class="intro">Select how you would like updates delivered. Your choice will be used for future notifications.</p>
           </section>

           <section class="form-section" aria-labelledby="page-title">
             <form id="notification-form">
               ${NotificationQuestion()}
               <div class="submit-row">
                 <button type="submit">Submit</button>
                 <p class="status" id="form-status" aria-live="polite"></p>
               </div>
             </form>
           </section>
         </div>
       `;
     }

     document.querySelector("#main-content").innerHTML = App();

     document.querySelector("#notification-form").addEventListener("submit", function (event) {
       event.preventDefault();
       const data = new FormData(event.currentTarget);
       const selection = data.get("notificationPreference");
       const status = document.querySelector("#form-status");
       status.textContent = "Preference saved: " + selection;
     });
   </script>
 </body>
 </html>

